-- Move listings off the old flat categories, then remove them.
do $$
declare m record; new_id uuid; old_id uuid;
begin
  for m in select * from (values
    ('food-beverage', 'food-beverages'),
    ('agriculture', 'agriculture-farm-fisheries'),
    ('health-beauty', 'beauty-wellness'),
    ('home-living', 'home-furniture-living'),
    ('electronics', 'mobile-gadgets'),
    ('construction-hardware', 'construction-hardware-industrial'),
    ('packaging-printing', 'packaging-printing-signage'),
    ('auto-motor', 'automotive-moto-ev'),
    ('crafts-gifts', 'gifts-crafts-personalized'),
    ('school-office', 'school-office-educational'),
    ('services', 'professional-business-services'),
    ('real-estate', 'real-estate-commercial'),
    ('import-brokerage', 'logistics-courier-pasabuy--customs-brokerage'),
    ('trucking-logistics', 'logistics-courier-pasabuy--trucking'),
    ('couriers-pasabuy', 'logistics-courier-pasabuy--pasabuy'),
    ('advertising-marketing', 'advertising-marketing-creative'),
    ('catering-concession', 'events-catering-hospitality--catering'),
    ('accounting-tax', 'professional-business-services--accounting'),
    ('rebrand-giveaways', 'gifts-crafts-personalized--corporate-giveaways')
  ) as t(old_slug, new_slug) loop
    select id into old_id from public.categories where slug = m.old_slug;
    select id into new_id from public.categories where slug = m.new_slug;
    if old_id is not null and new_id is not null then
      update public.listings set category_id = new_id where category_id = old_id;
      delete from public.categories where id = old_id;
    end if;
  end loop;
end $$;
